"""D193: the installer's newest engines, picked before the daemon's packages are in."""

from pathlib import Path

import pytest

from nestd.updates.first_install import main

# As `uv export --format requirements.txt` writes it.
REQUIREMENTS = """\
# This file was autogenerated by uv via the following command:
#    uv export --frozen --no-dev --no-emit-project --format requirements.txt
anyio==4.9.0 \\
    --hash=sha256:aaa \\
    --hash=sha256:bbb
    # via
    #   claude-agent-sdk
    #   httpx
claude-agent-sdk==0.2.177 \\
    --hash=sha256:ccc \\
    --hash=sha256:ddd
    # via nestd
httpx==0.28.1 \\
    --hash=sha256:eee
openai-codex-cli-bin==0.163.0 \\
    --hash=sha256:fff
    # via nestd
"""


def run(tmp_path: Path, newest: dict[str, str | None] | OSError) -> tuple[int, Path]:
    source, rest = tmp_path / "requirements.txt", tmp_path / "rest.txt"
    source.write_text(REQUIREMENTS, encoding="utf-8")

    def ask(package: str) -> str | None:
        if isinstance(newest, OSError):
            raise newest
        return newest[package]

    return main([str(source), str(rest)], ask), rest


def test_a_newer_engine_replaces_its_pin_and_the_rest_keeps_their_hashes(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    code, rest = run(tmp_path, {"claude-agent-sdk": "0.2.180", "openai-codex-cli-bin": "0.163.0"})

    assert code == 0
    assert capsys.readouterr().out == "claude-agent-sdk==0.2.180\n"
    kept = rest.read_text(encoding="utf-8")
    assert "claude-agent-sdk==" not in kept
    assert "sha256:ccc" not in kept
    assert "sha256:ddd" not in kept
    # The other packages, the unchanged engine and the notes under them stay whole.
    assert "anyio==4.9.0 \\\n    --hash=sha256:aaa \\\n    --hash=sha256:bbb\n" in kept
    assert "#   claude-agent-sdk\n" in kept
    assert "openai-codex-cli-bin==0.163.0 \\\n    --hash=sha256:fff\n" in kept
    assert kept.startswith("# This file was autogenerated")


def test_both_engines_newer(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    code, rest = run(tmp_path, {"claude-agent-sdk": "0.2.180", "openai-codex-cli-bin": "0.167.1"})

    assert code == 0
    assert capsys.readouterr().out.splitlines() == [
        "claude-agent-sdk==0.2.180",
        "openai-codex-cli-bin==0.167.1",
    ]
    kept = rest.read_text(encoding="utf-8")
    assert "claude-agent-sdk==" not in kept
    assert "openai-codex-cli-bin==" not in kept
    assert "httpx==0.28.1 \\\n    --hash=sha256:eee\n" in kept


@pytest.mark.parametrize(
    "newest",
    [
        {"claude-agent-sdk": "0.2.177", "openai-codex-cli-bin": "0.163.0"},
        # A pulled release, a prerelease and an older one never count.
        {"claude-agent-sdk": None, "openai-codex-cli-bin": "0.164.0rc1"},
        {"claude-agent-sdk": "0.2.170", "openai-codex-cli-bin": "0.163.0"},
        OSError("no network"),
    ],
    ids=["same", "pulled-or-prerelease", "older", "offline"],
)
def test_nothing_newer_or_no_network_keeps_the_release_engines(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
    newest: dict[str, str | None] | OSError,
) -> None:
    code, rest = run(tmp_path, newest)

    assert code == 1
    assert capsys.readouterr().out == ""
    assert not rest.exists()
